<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'; import { api } from '@/api'; import type { BudgetSpace,Category,TransactionKind } from '@/types'
const categories=ref<Category[]>([]),spaces=ref<BudgetSpace[]>([]); const form=ref<{name:string;budgetSpaceId:string;appliesTo:TransactionKind;parentCategoryId:string}>({name:'',budgetSpaceId:'',appliesTo:'expense',parentCategoryId:''})
const parents=computed(()=>categories.value.filter(c=>!c.parentCategoryId&&c.budgetSpaceId===form.value.budgetSpaceId&&c.appliesTo===form.value.appliesTo)); async function load(){[categories.value,spaces.value]=await Promise.all([api.categories(),api.spaces()]);form.value.budgetSpaceId ||=spaces.value[0]?.id??''} async function save(){await api.createCategory({...form.value,parentCategoryId:form.value.parentCategoryId||null,sortOrder:categories.value.length});form.value.name='';form.value.parentCategoryId='';await load()} onMounted(load)
</script>
<template><div class="grid two wide-first"><section class="panel"><div class="panel-title"><h2>Kategorie</h2><span>{{categories.length}} pozycji</span></div><div v-for="c in categories.filter(c=>!c.parentCategoryId)" :key="c.id" class="category"><strong>{{c.name}}</strong><small>{{c.appliesTo==='expense'?'Wydatek':'Przychód'}}</small><div v-for="child in categories.filter(x=>x.parentCategoryId===c.id)" :key="child.id" class="subcategory">{{child.name}}</div></div></section><section class="panel"><h2>Dodaj kategorię</h2><form @submit.prevent="save"><label>Nazwa<input v-model.trim="form.name" required/></label><label>Portfel<select v-model="form.budgetSpaceId"><option v-for="s in spaces" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Rodzaj<select v-model="form.appliesTo"><option value="expense">Wydatek</option><option value="income">Przychód</option></select></label><label>Kategoria nadrzędna <select v-model="form.parentCategoryId"><option value="">Brak — kategoria główna</option><option v-for="c in parents" :key="c.id" :value="c.id">{{c.name}}</option></select></label><button class="button primary">Dodaj kategorię</button></form></section></div></template>
